Given an array of n integers and an integer k, the task is to find the number of subarrays such that all elements in each subarray are greater than k.Examples: Input: arr[] = {3, 4, 5, 6, 7, 2, 10, 11}, k= 5 Output: 6 The possible subarrays are {6}, {7}, {6, 7}, {10}, {11} and {10, 11}.Input: arr[] = {8, 25, 10, 19, 19, 18, 20, 11, 18}, k = 13 Output: 12  Table of Content[Naive Approach] Using two nested loops[Expected Approach] Using Sliding Window[Naive Approach] Using two nested loopsThe idea is to use two nested loops where the outer loop selects the starting point of potential subarrays, and for each starting point, the inner loop extends the subarray as long as all elements encountered are greater than k. When we find a valid subarray (all elements > k), we increment our count. The inner loop breaks as soon as we find an element less than or equal to k since any further extension of that subarray would be invalid. 
            C++

    // C++ program to print the number of subarrays such
// that all elements are greater than K
#include <iostream>
#include <vector>
using namespace std;

// Function to count number of subarrays
int countSubarrays(vector<int> &arr, int k) {

    int n = arr.size();
    int count = 0;

    // First loop to select starting point
    for (int i = 0; i < n; i++) {

        // Second loop to extend the subarray
        for (int j = i; j < n; j++) {

            // If we find an element <= x, break
            if (arr[j] <= k)
                break;

            // If all elements so far are > x,
            // we found a valid subarray
            count++;
        }
    }
    return count;
}

int main() {
    vector<int> arr = {3, 4, 5, 6, 7, 2, 10, 11};
    int k = 5;
    cout << countSubarrays(arr, k);
    return 0;
}


